/* 正式版互動：資料只留在此瀏覽器的 localStorage。 */
const formalPets=[['raccoon','小浣熊'],['penguin','小企鵝'],['rabbit','小兔子'],['fox','小狐狸'],['bear','小熊'],['cat','小貓'],['shiba','柴犬'],['capybara','水豚'],['owl','小貓頭鷹'],['otter','小水獺']];
const formalKey='credit-pet-island-formal-v1';
const fToday=()=>new Date(), fMonth=()=>`${fToday().getFullYear()}-${String(fToday().getMonth()+1).padStart(2,'0')}`, fIso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const fMoney=n=>new Intl.NumberFormat('zh-TW',{style:'currency',currency:'TWD',maximumFractionDigits:0}).format(n||0);
const shopItems=[{id:'scarf',name:'薄荷圍巾',cost:20,kind:'配件',scope:'pet',sprite:0},{id:'backpack',name:'探險背包',cost:30,kind:'配件',scope:'pet',sprite:1},{id:'hat',name:'蘑菇帽',cost:40,kind:'配件',scope:'pet',sprite:2},{id:'cottage',name:'暖暖小屋',cost:45,kind:'家具',scope:'island',sprite:3},{id:'plant',name:'月光盆栽',cost:25,kind:'家具',scope:'island',sprite:4},{id:'tea',name:'茶點角落',cost:35,kind:'家具',scope:'island',sprite:5}];
function fEnsureGame(){formal.unlockedItems??=['scarf'];formal.islandItems??=[];formal.cards.forEach(c=>{c.coins??=0;c.snacks??=0;c.accessories??=[]})}
let formal=JSON.parse(localStorage.getItem(formalKey)||localStorage.getItem('credit-pet-island-v2')||localStorage.getItem('credit-pet-island-v1')||'null')||fSeed();
if([2,10].includes(formal.cards?.length)&&formal.cards.every(c=>/^demo\d+$/.test(c.id))){formal=fSeed();localStorage.setItem(formalKey,JSON.stringify(formal))}

function fSeed(){const card=(id,petType,petName,bank,cardName,last4,dueDay)=>({id,bank,cardName,last4,statementDay:5,dueDay,petType,petName,stage:'juvenile',xp:0,coins:20,snacks:1,accessories:[],active:true,note:'剛入住小島的新夥伴',createdAt:fIso(fToday()),bills:[]});return{cards:[card('demo1','raccoon','回饋寶','國泰世華','Cube 卡','1234',20),card('demo2','penguin','旅遊球','玉山銀行','U Bear','5678',25)],unlockedItems:['scarf'],islandItems:[]}};
function fSave(){localStorage.setItem(formalKey,JSON.stringify(formal));fRender()}
function fCard(id){return formal.cards.find(c=>c.id===id)}
function fPet(c){return formalPets.find(p=>p[0]===c.petType)?.[1]||'寵物'}
function fPos(type){const i=formalPets.findIndex(p=>p[0]===type);return `${(i%5)*25}% ${i>4?'100%':'0%'}`}
function fBill(c){return c.bills.find(b=>b.month===fMonth())||[...c.bills].filter(b=>!b.paid&&b.month<fMonth()).sort((a,b)=>b.month.localeCompare(a.month))[0]}
function fDue(c,b){const [y,m]=b.month.split('-').map(Number),day=Math.min(b.dueDay??c.dueDay,new Date(y,m,0).getDate());return new Date(y,m-1,day,12)}
function fDate(d){return d.toLocaleDateString('zh-TW',{month:'numeric',day:'numeric'})}
function fPrev(m){const [y,mo]=m.split('-').map(Number),d=new Date(y,mo-2,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function fStreak(c){let run=0,max=0,last='';[...c.bills].sort((a,b)=>a.month.localeCompare(b.month)).forEach(b=>{if(b.paid&&b.onTime){run=last===fPrev(b.month)?run+1:1;max=Math.max(max,run)}else run=0;last=b.month});return max}
function fStreakThrough(c,month){let run=0,check=month;while(true){const b=c.bills.find(x=>x.month===check);if(!b?.paid||!b.onTime)return run;run++;check=fPrev(check)}}
function fGrowth(c){if(fStreak(c)>=3)c.stage='adult';else if(!c.stage)c.stage='juvenile'}
function fState(c,b){if(!b)return['等待帳單','normal','normal'];if(b.paid){const happy=fStreakThrough(c,b.month)>=3;return[happy?'連續 3 個月準時繳款！':'已繳款',happy?'paid-streak':'paid',happy?'happy':'normal']}const days=Math.ceil((fDue(c,b)-new Date(fToday().getFullYear(),fToday().getMonth(),fToday().getDate()))/86400000);if(days<0)return['逾期未繳，請確認是否已繳款','overdue','angry'];if(days<=3)return[days===0?'今天到期！':`剩 ${days} 天要繳款`,'urgent','worried'];return[`還有 ${days} 天要繳款`,days<=7?'soon':'normal','normal']}
function fMoodPosition(m){return({normal:'0% 0%',happy:'100% 0%',worried:'0% 100%',angry:'100% 100%'}[m]||'0% 0%')}
function fEmotionSheet(c){const group=formalPets.findIndex(p=>p[0]===c.petType)<5?'a':'b';return `pets-emotions-${c.stage==='adult'?'adult-':''}${group}.png`}
function fEmotionPosition(c,mood){const i=formalPets.findIndex(p=>p[0]===c.petType)%5,row=({normal:0,happy:1,worried:2,angry:3}[mood]??0);return `${i*25}% ${row*100/3}%`}
function fMood(){return ''}
function fSprite(c,extra=''){const mood=fState(c,fBill(c))[2];return `<div class="pet-art ${extra}" style="background-image:url('${fEmotionSheet(c)}');background-position:${fEmotionPosition(c,mood)};background-size:500% 400%!important"></div>`}
function fShopPos(item){const i=typeof item==='string'?shopItems.findIndex(x=>x.id===item):item.sprite;return `${(i%3)*50}% ${i>2?'100%':'0%'}`}
function fShopArt(item,extra=''){return `<i class="shop-art ${extra}" style="background-position:${fShopPos(item)}"></i>`}
function fUnlockNext(){fEnsureGame();const next=shopItems.find(item=>!formal.unlockedItems.includes(item.id));if(next)formal.unlockedItems.push(next.id);return next}
function fOwnedItem(c,id){return !!c&&c.accessories.includes(id)}
function formalShop(){fEnsureGame();const active=formal.cards.filter(c=>c.active),selected=active[0];document.querySelector('#shopContent').innerHTML=`<p class="subtle">成年夥伴每次準時繳款會解鎖下一件商品；解鎖後仍要用金幣購買。</p><div class="shop-grid">${shopItems.map(item=>{const unlocked=formal.unlockedItems.includes(item.id),island=formal.islandItems.includes(item.id),owned=selected&&fOwnedItem(selected,item.id);const state=!unlocked?'尚未解鎖':item.scope==='island'&&island?'已放在小島':item.scope==='pet'&&owned?`已給${selected.petName}`:`${item.cost} 枚金幣`;const select=item.scope==='pet'?`<select id="owner-${item.id}">${active.map(c=>`<option value="${c.id}">${c.petName}</option>`).join('')}</select>`:'';return `<article class="shop-item ${unlocked?'':'locked'}">${fShopArt(item)}<strong>${item.name}</strong><small>${item.kind}・${state}</small>${select}<button type="button" ${unlocked?'':'disabled'} onclick="formalBuy('${item.id}',document.querySelector('#owner-${item.id}')?.value)">${!unlocked?'完成成長任務解鎖':item.scope==='island'&&island?'已擁有':'購買'}</button></article>`}).join('')}</div>`;fOpen('#shopDialog')}
function formalBuy(id,ownerId){fEnsureGame();const item=shopItems.find(x=>x.id===id),owner=ownerId&&fCard(ownerId);if(!item||!formal.unlockedItems.includes(id))return;if(item.scope==='island'&&formal.islandItems.includes(id)){fToast('這件家具已經在小島上了。');return}if(item.scope==='pet'&&fOwnedItem(owner,id)){fToast(`${owner.petName} 已經有這件配件了。`);return}const buyer=owner||formal.cards.find(c=>c.active);if(!buyer||buyer.coins<item.cost){fToast(`需要 ${item.cost} 枚金幣才能購買。`);return}buyer.coins-=item.cost;if(item.scope==='island')formal.islandItems.push(id);else owner.accessories.push(id);fSave();formalShop();fToast(`${item.name} 已加入小島！`)}
function fToast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2800)}
function fOpen(id){document.querySelector(id).showModal()}function fClose(){document.querySelectorAll('dialog[open]').forEach(d=>d.close())}
function fStats(c){const paid=c.bills.filter(b=>b.paid);return [paid.filter(b=>b.onTime).length,fStreak(c),c.bills.length]}
function fCardHtml(c,album=false){const b=fBill(c),[label,kind,mood]=fState(c,b),[ontime,streak,count]=fStats(c);if(album)return `<article class="pet-card travel-card"><div class="pet-stage">${fSprite(c,'stage-sprite')}</div><div class="card-body">${fMood('happy')}<div class="card-top"><div><h3>${c.petName} <small>｜${c.stage==='adult'?'成年':'幼年'}${fPet(c)}</small></h3><p class="subtle">${c.bank}・${c.cardName}・末四碼 ${c.last4}</p></div><span class="pill">旅行中</span></div><div class="amount small-amount">陪伴紀錄</div><p class="due">${count} 筆帳單・準時繳款 ${ontime} 次<br>旅行日：${c.travelDate||'—'}</p><div class="card-actions"><button onclick="formalDetail('${c.id}')">查看回憶帳本</button><button class="pay" onclick="formalReturn('${c.id}')">邀請回小島</button></div></div></article>`;
const actions=b?`${b.paid?`<button onclick="formalDetail('${c.id}')">查看帳本</button>`:`<button class="pay" onclick="formalPay('${c.id}','${b.id}')">去繳款</button><button onclick="formalBill('${c.id}','${b.id}')">修改帳單</button>`}<button onclick="formalSettings('${c.id}')">卡片設定</button><button onclick="formalTravel('${c.id}')">去旅行</button>`:`<button class="pay" onclick="formalBill('${c.id}')">新增本月帳單</button><button onclick="formalDetail('${c.id}')">查看帳本</button><button onclick="formalSettings('${c.id}')">卡片設定</button><button onclick="formalTravel('${c.id}')">去旅行</button>`;
return `<article class="pet-card status-${kind}"><div class="pet-stage">${fSprite(c,'stage-sprite')}</div><div class="card-body">${fMood(mood)}<div class="card-top"><div><h3>${c.petName} <small>｜${c.stage==='adult'?'成年':'幼年'}${fPet(c)}</small></h3><p class="subtle">${c.bank}・${c.cardName}・末四碼 ${c.last4}</p></div><span class="pill ${kind}">${label}</span></div>${b?`<div class="amount">${fMoney(b.amount)}</div><p class="due">結帳日：每月 ${b.statementDay??c.statementDay} 日<br>繳款截止日：${fDate(fDue(c,b))}</p>`:`<div class="amount">尚未輸入</div><p class="due">結帳日：每月 ${c.statementDay} 日<br>繳款截止日：每月 ${c.dueDay} 日</p>`}<div class="card-actions">${actions}</div></div></article>`}
const mapPlots={raccoon:[16,20],penguin:[45,19],rabbit:[64,19],fox:[84,21],bear:[17,47],cat:[32,45],shiba:[60,47],capybara:[35,72],owl:[88,46],otter:[66,71]};
const mapPlotsMobile=Object.fromEntries(Object.entries(mapPlots).map(([type,[x,y]])=>[type,[x,+(y*.5625).toFixed(2)]]));
const habitatNames={raccoon:'森林樹洞',penguin:'冰瀑湖畔',rabbit:'胡蘿蔔花園',fox:'秋日岩洞',bear:'大樹木屋',cat:'花園小屋',shiba:'訓練草坪',capybara:'溫泉池畔',owl:'星空觀測台',otter:'河灣小屋'};
function fMapRender(){const map=document.querySelector('#mapCanvas');if(!map)return;fEnsureGame();const owned={};formal.cards.filter(c=>c.active).forEach(c=>{if(!owned[c.petType])owned[c.petType]=c});const furniture=formal.islandItems.map((id,i)=>`<i class="map-furniture" style="left:${12+i*15}%;top:82%;background-position:${fShopPos(id)}"></i>`).join('');map.innerHTML=furniture+Object.keys(mapPlots).map(type=>{const [x,y]=mapPlots[type],c=owned[type];if(!c)return `<button class="map-habitat" style="left:${x}%;top:${y}%" onclick="formalAdopt('${type}')" aria-label="領養${fPet({petType:type})}">${habitatNames[type]}<small>點此領養</small></button>`;const mood=fState(c,fBill(c))[2],gear=c.accessories.slice(0,2).map(id=>`<i class="map-gear" style="background-position:${fShopPos(id)}"></i>`).join('');return `<button class="map-pet" style="left:${x}%;top:${y}%;background-image:url('${fEmotionSheet(c)}');background-position:${fEmotionPosition(c,mood)};background-size:500% 400%" onclick="formalDetail('${c.id}')" aria-label="查看${c.petName}的帳本">${gear}<span>${c.petName}</span></button>`}).join('');const count=Object.keys(owned).length,due=formal.cards.filter(c=>c.active).map(c=>fBill(c)).filter(b=>b&&!b.paid).length;document.querySelector('#mapOwned').textContent=`已入住 ${count}／10 隻`;document.querySelector('#mapPets').textContent=`夥伴 ${count} 隻`;document.querySelector('#mapCoins').textContent=`金幣 ${formal.cards.reduce((n,c)=>n+(c.coins||0),0)} 枚`;document.querySelector('#mapTask').textContent=due?`今日任務：照顧 ${due} 位待繳夥伴`:'今日任務：本月帳單都已完成！'}
const fMapRenderBase=fMapRender;fMapRender=function(){fMapRenderBase();const snacks=document.querySelector('#mapSnacks');if(snacks)snacks.textContent=`小點心 ${formal.cards.reduce((n,c)=>n+(c.snacks||0),0)} 個`}
const fMapRenderResponsive=fMapRender;fMapRender=function(){const mobile=window.matchMedia('(max-width:650px)').matches,original=mobile?Object.fromEntries(Object.entries(mapPlots).map(([type,point])=>[type,[...point]])):null;if(mobile)Object.keys(mapPlots).forEach(type=>mapPlots[type][1]=mapPlotsMobile[type][1]);fMapRenderResponsive();if(original)Object.keys(original).forEach(type=>mapPlots[type]=original[type])}
function fRender(){fEnsureGame();formal.cards.forEach(fGrowth);const active=formal.cards.filter(c=>c.active),travel=formal.cards.filter(c=>!c.active),due=active.map(c=>[c,fBill(c)]).filter(([,b])=>b&&!b.paid);document.querySelector('#totalDue').textContent=fMoney(due.reduce((n,[,b])=>n+b.amount,0));document.querySelector('#activeDue').textContent=`${due.length} 張`;const closest=[...due].sort((x,y)=>fDue(x[0],x[1])-fDue(y[0],y[1]))[0];document.querySelector('#closestDue').textContent=closest?fDate(fDue(closest[0],closest[1])):'全部完成';document.querySelector('#coinTotal').textContent=`${formal.cards.reduce((n,c)=>n+(c.coins||0),0)} 枚`;document.querySelector('#heroMessage').textContent=due.length?`還有 ${due.length} 張卡等待照顧，先看看最近要到期的夥伴。`:'本月已輸入的帳單都處理完成，小島的夥伴正在開心休息！';document.querySelector('#cardGrid').innerHTML=active.map(c=>fCardHtml(c)).join('');document.querySelector('#albumGrid').innerHTML=travel.map(c=>fCardHtml(c,true)).join('');document.querySelector('#islandEmpty').classList.toggle('hidden',!!active.length);document.querySelector('#albumEmpty').classList.toggle('hidden',!!travel.length);document.querySelector('#albumCount').textContent=travel.length;fMapRender()}

function formalBill(cid,bid=''){const c=fCard(cid),b=c.bills.find(x=>x.id===bid);document.querySelector('#billForm').reset();document.querySelector('#billCardId').value=cid;document.querySelector('#billMonth').value=b?.month||fMonth();document.querySelector('#billAmount').value=b?.amount??'';document.querySelector('#billNote').value=b?.note||'';document.querySelector('#billForm').dataset.billId=bid;document.querySelector('#billTitle').textContent=`幫${c.petName}${b?'調整帳本':'整理帳本'}`;fOpen('#billDialog')}
function formalPay(cid,bid){const c=fCard(cid),b=c.bills.find(x=>x.id===bid);document.querySelector('#payForm').reset();document.querySelector('#payCardId').value=cid;document.querySelector('#payBillId').value=bid;document.querySelector('#paidAt').value=fIso(fToday());document.querySelector('#payTitle').textContent=`幫${c.petName}完成繳款`;document.querySelector('#paySummary').textContent=`本期帳單 ${fMoney(b.amount)}・截止日 ${fDue(c,b).toLocaleDateString('zh-TW')}`;fOpen('#payDialog')}
function formalTravel(id){const c=fCard(id);document.querySelector('#travelCardId').value=id;document.querySelector('#travelTitle').textContent=`要讓「${c.petName}」去旅行嗎？`;fOpen('#travelDialog')}
function formalReturn(id){const c=fCard(id);c.active=true;delete c.travelDate;fSave();fToast(`歡迎 ${c.petName} 回到小島！`)}
function formalSettings(id){const c=fCard(id),g=k=>document.querySelector('#s'+k);g('id').value=id;g('petName').value=c.petName;g('bank').value=c.bank;g('cardName').value=c.cardName;g('last4').value=c.last4;g('statementDay').value=c.statementDay;g('dueDay').value=c.dueDay;g('note').value=c.note||'';fOpen('#settingsDialog')}
function formalDetail(id){const c=fCard(id),[ontime,streak,count]=fStats(c),bills=[...c.bills].sort((a,b)=>b.month.localeCompare(a.month));document.querySelector('#detailContent').innerHTML=`<div class="detail-head">${fSprite(c,'detail-sprite')}<div><p class="eyebrow">${c.active?'信用卡小島':'回憶帳本'}</p><h2>${c.petName}的${c.active?'帳本':'回憶帳本'}</h2><p class="subtle">${c.bank}・${c.cardName}・末四碼 ${c.last4}<br>${c.stage==='adult'?'成年夥伴':'幼年夥伴'}・${c.coins||0} 枚金幣</p></div></div><div class="formal-record"><span>準時繳款<strong>${ontime} 次</strong></span><span>最長連續<strong>${streak} 個月</strong></span><span>累積帳單<strong>${count} 筆</strong></span></div><table class="history"><thead><tr><th>年月</th><th>帳單</th><th>截止日</th><th>狀態</th><th>繳款日</th><th></th></tr></thead><tbody>${bills.map(b=>`<tr><td>${b.month}</td><td>${fMoney(b.amount)}</td><td>${fDate(fDue(c,b))}</td><td>${b.paid?(b.onTime?'準時已繳':'已繳'):'待繳'}</td><td>${b.paidAt||'—'}</td><td>${c.active?`<button class="table-button" onclick="fClose();formalBill('${c.id}','${b.id}')">修改</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6">還沒有帳單紀錄</td></tr>'}</tbody></table>`;fOpen('#detailDialog')}

document.head.insertAdjacentHTML('beforeend',`<style>.formal-mood{position:absolute;right:12px;top:-25px;width:58px;height:58px;background-image:url('pet-moods.png');background-size:200% 200%;background-repeat:no-repeat;filter:drop-shadow(0 3px 3px #20384422);z-index:2}.pet-card{position:relative}.pet-card .card-body{position:relative}.small-amount{font-size:1.3rem}.formal-record{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:16px 0}.formal-record span{background:#edf8f4;border-radius:10px;padding:9px;color:#54736f;font-size:.73rem}.formal-record strong{display:block;color:#28736e;font-size:1rem;margin-top:2px}.table-button{border:0;border-radius:7px;padding:4px 7px;background:#eff7f3;color:#28736e;font-weight:700}.formal-settings{display:grid;gap:10px}@media(max-width:600px){.formal-record{grid-template-columns:1fr}.formal-mood{width:48px;height:48px;top:-19px}.history{font-size:.75rem}}</style><dialog id="settingsDialog"><form id="settingsForm"><button type="button" class="close" data-fclose>×</button><p class="eyebrow">卡片設定</p><h2>調整信用卡資料</h2><input id="sid" type="hidden"><label>寵物名稱<input id="spetName" maxlength="12" required></label><div class="form-grid"><label>銀行名稱<input id="sbank" required></label><label>卡片名稱<input id="scardName" required></label><label>卡號末四碼<input id="slast4" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" required></label><label>結帳日<select id="sstatementDay"></select></label><label>未來帳單截止日<select id="sdueDay"></select></label></div><label>卡片備註<textarea id="snote" rows="2"></textarea></label><p class="subtle">日期變更只會套用到之後新增的帳單；舊帳本會保留原本的截止日。</p><div class="dialog-actions"><button type="button" class="secondary" data-fclose>取消</button><button class="primary">儲存設定</button></div></form></dialog>`);
document.head.insertAdjacentHTML('beforeend',`<style>.pet-card{overflow:hidden}.pet-stage{height:205px;display:grid;place-items:end center;background:radial-gradient(circle at 50% 18%,#ffffffcc 0 18%,transparent 19%),linear-gradient(160deg,#d5f2e7,#aee4d0);border-bottom:3px solid #dff0e9;position:relative}.pet-stage:after{content:'棲地';position:absolute;left:13px;bottom:10px;border-radius:99px;background:#ffffffc9;color:#46817b;font-size:.7rem;font-weight:800;padding:4px 8px}.stage-sprite{width:100%;height:205px;background-size:500% 200%!important;background-repeat:no-repeat!important;background-color:transparent!important;filter:drop-shadow(0 8px 5px #397b7d2b);transform:scale(1.08);transition:transform .35s ease}.pet-card:hover .stage-sprite{transform:scale(1.14)}.detail-sprite{width:120px!important;height:100px!important;border-radius:14px;background-size:500% 200%!important;background-repeat:no-repeat!important;background-color:#dff4e8!important}.pet-option{background-image:url('pets-juvenile.png')!important;background-size:500% 200%!important;background-repeat:no-repeat!important;background-color:#eaf7f1}.pet-option.selected{box-shadow:0 0 0 3px #d9f1e8,0 6px 13px #397b7d2b}@media(max-width:780px){.pet-stage{height:185px}.stage-sprite{height:185px}}</style>`);
