document.querySelectorAll('.add-trigger,#addCardBtn,#quickAdd').forEach(b=>b.onclick=()=>{document.querySelector('#cardForm').reset();document.querySelector('#petType').value='raccoon';document.querySelectorAll('.pet-option').forEach(x=>x.classList.toggle('selected',x.dataset.pet==='raccoon'));fOpen('#cardDialog')});
document.querySelector('#cardForm').addEventListener('submit',e=>{e.preventDefault();const g=id=>document.querySelector('#'+id).value,c={id:crypto.randomUUID(),bank:g('bank'),cardName:g('cardName'),last4:g('last4'),statementDay:+g('statementDay'),dueDay:+g('dueDay'),petType:g('petType'),petName:g('petName'),stage:'juvenile',xp:0,coins:0,snacks:0,accessories:[],active:true,note:g('note'),createdAt:fIso(fToday()),bills:[]};formal.cards.push(c);fClose();fSave();fToast(`${c.petName} 已經入住信用卡小島！`)});
document.querySelector('#billForm').addEventListener('submit',e=>{e.preventDefault();const c=fCard(document.querySelector('#billCardId').value),bid=e.currentTarget.dataset.billId||'',m=document.querySelector('#billMonth').value,amount=+document.querySelector('#billAmount').value,note=document.querySelector('#billNote').value;if(!bid&&c.bills.some(b=>b.month===m)){fToast('這個月份已有帳單，請從帳本修改。');return}const b=bid&&c.bills.find(x=>x.id===bid);if(b){b.month=m;b.amount=amount;b.note=note}else{c.bills.push({id:crypto.randomUUID(),month:m,amount,note,statementDay:c.statementDay,dueDay:c.dueDay,paid:false});c.xp=(c.xp||0)+10}fClose();fSave();fToast(bid?'帳單已更新。':`${c.petName} 獲得 10 點整理帳本經驗值！`)});
document.querySelector('#payForm').addEventListener('submit',e=>{e.preventDefault();const c=fCard(document.querySelector('#payCardId').value),b=c.bills.find(x=>x.id===document.querySelector('#payBillId').value);b.paid=true;b.paidAt=document.querySelector('#paidAt').value;b.method=document.querySelector('#paymentMethod').value;b.note=document.querySelector('#payNote').value;const paidDate=new Date(`${b.paidAt}T12:00:00`),daysEarly=Math.floor((fDue(c,b)-paidDate)/86400000);b.onTime=daysEarly>=0;c.xp=(c.xp||0)+30;let coins=b.onTime?10:0,snacks=0,reward='';if(b.onTime&&daysEarly>=7){snacks=1;reward='提早 7 天完成，獲得金幣與小點心！'}else if(b.onTime&&daysEarly<=3){coins+=5;snacks=1;reward='獲得額外準時獎勵！'}c.coins=(c.coins||0)+coins;c.snacks=(c.snacks||0)+snacks;const was=c.stage;fGrowth(c);const unlocked=b.onTime&&c.stage==='adult'?fUnlockNext():null;fClose();fSave();fToast(unlocked?`${c.petName}${was==='juvenile'?'升級成年並':'持續準時，'}解鎖「${unlocked.name}」，可到商店用金幣購買！`:b.onTime?`${c.petName} 獲得 ${coins} 枚金幣${snacks?'與 1 個小點心':''}。${reward}`:'已記錄繳款。')});
document.querySelector('#travelForm').addEventListener('submit',e=>{e.preventDefault();const c=fCard(document.querySelector('#travelCardId').value);c.active=false;c.travelDate=fIso(fToday());fClose();fSave();fToast(`${c.petName} 已經住進回憶相簿。`)});
document.querySelector('#settingsForm').addEventListener('submit',e=>{e.preventDefault();const c=fCard(document.querySelector('#sid').value),g=k=>document.querySelector('#s'+k).value;c.petName=g('petName');c.bank=g('bank');c.cardName=g('cardName');c.last4=g('last4');c.statementDay=+g('statementDay');c.dueDay=+g('dueDay');c.note=g('note');fClose();fSave();fToast('卡片設定已儲存。')});
document.querySelector('#resetBtn').onclick=()=>{if(confirm('要回復成正式版示範資料嗎？目前輸入的資料會被清除。')){formal=fSeed();fSave();fToast('已回復試玩資料。')}};
['statementDay','dueDay'].forEach(id=>document.querySelector('#'+id).innerHTML=Array.from({length:31},(_,i)=>`<option value="${i+1}">每月 ${i+1} 日</option>`).join(''));
