document.head.insertAdjacentHTML('beforeend',`<style>body{background:#b8eafa}.topbar,.hero,.stats,.tabs,#islandView,#albumView{display:none!important}main{width:min(1280px,100%);padding:18px clamp(8px,2vw,28px) 28px}.map-view{margin:0!important}.map-heading{display:none}.map-canvas{border-radius:28px;min-height:0}.map-habitat{border:0;cursor:pointer;pointer-events:auto;box-shadow:0 3px 8px #183f5430;transition:transform .18s,background .18s}.map-habitat:hover{transform:translate(-50%,-55%) scale(1.1);background:#fff}.hud-album{border:1px solid #ffffff46;background:#ffffff20;color:#fff;border-radius:99px;padding:6px 10px;font:inherit;font-size:.77rem;font-weight:700}.hud-clear{border-color:#ffd0ca;background:#b94d45}.map-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.map-actions button{border:0;border-radius:11px;padding:10px 12px;font:inherit;font-size:.84rem;font-weight:800;background:#eff7f3;color:#28736e}.map-actions .map-pay{background:#28736e;color:#fff}.map-album-list{display:grid;gap:10px}.map-album-entry{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:11px;border:1px solid #d8e9e2;border-radius:12px}.map-album-entry strong,.map-album-entry small{display:block}.map-album-entry small{color:#6d7a80;margin-top:2px}.map-album-entry button{border:0;border-radius:9px;background:#eff7f3;color:#28736e;padding:7px 9px;font:inherit;font-size:.8rem;font-weight:800}@media(max-width:650px){main{padding:8px}.map-canvas{border-radius:16px}.game-hud{margin-bottom:9px}.hud-stats{padding-left:0}.map-pet{width:15%;min-width:42px}.map-habitat{min-width:44px;min-height:32px}.hud-album{font-size:.7rem}}</style>`);
document.head.insertAdjacentHTML('beforeend',`<style>.shop-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.shop-item{border:1px solid #d5e8e0;border-radius:13px;padding:9px;display:flex;flex-direction:column;gap:5px;text-align:center;background:#fbfffc}.shop-item.locked{opacity:.52;filter:grayscale(.7)}.shop-item strong{font-size:.84rem}.shop-item small{font-size:.7rem;color:#617775;min-height:30px}.shop-item select,.shop-item button{margin:0;width:100%;padding:6px;font-size:.72rem}.shop-item button{border:0;border-radius:8px;background:#28736e;color:#fff;font-weight:800}.shop-item button:disabled{background:#aebcb8}.shop-art,.map-gear,.map-furniture{display:block;background-image:url('island-shop-items.png');background-size:300% 200%;background-repeat:no-repeat}.shop-art{height:72px}.map-gear{position:absolute;width:34%;height:34%;right:-7%;top:-11%;filter:drop-shadow(0 2px 2px #0005)}.map-furniture{position:absolute;width:11%;aspect-ratio:1;transform:translate(-50%,-50%);filter:drop-shadow(0 4px 3px #183f5444);z-index:3;pointer-events:none}@media(max-width:650px){body{min-height:100svh}main{min-height:100svh;padding:8px 8px 16px}.game-hud{position:sticky;top:0;z-index:8;border-radius:14px}.map-canvas{aspect-ratio:4/5;background-size:100% auto;background-position:center top}.map-pet{width:19%;min-width:46px}.map-habitat{max-width:74px;white-space:normal}.map-furniture{width:18%}.shop-grid{grid-template-columns:repeat(2,1fr)}.shop-art{height:82px}}</style>`);
function formalAdopt(type){fClose();document.querySelector('#cardForm').reset();document.querySelector('#petType').value=type;document.querySelectorAll('.pet-option').forEach(x=>x.classList.toggle('selected',x.dataset.pet===type));document.querySelector('#cardDialog h2').textContent=`領養${fPet({petType:type})}，入住${habitatNames[type]}`;fOpen('#cardDialog')}
function formalAlbum(){const trips=formal.cards.filter(c=>!c.active);document.querySelector('#mapAlbumContent').innerHTML=trips.length?`<div class="map-album-list">${trips.map(c=>`<div class="map-album-entry"><div><strong>${c.petName}｜${c.stage==='adult'?'成年':'幼年'}${fPet(c)}</strong><small>${c.bank}・末四碼 ${c.last4}・旅行日 ${c.travelDate||'—'}</small></div><button type="button" onclick="document.querySelector('#mapAlbumDialog').close();formalDetail('${c.id}')">查看帳本</button></div>`).join('')}</div>`:'<p class="subtle">目前沒有旅行中的夥伴。</p>';fOpen('#mapAlbumDialog')}
function formalClear(){if(confirm('要清空所有信用卡、寵物與回憶帳本資料嗎？此操作無法復原。')){formal={cards:[]};localStorage.setItem(formalKey,JSON.stringify(formal));fRender();fToast('小島已清空，可以重新領養夥伴。')}}
const mapBaseDetail=window.formalDetail;
window.formalDetail=function(id){mapBaseDetail(id);const c=fCard(id),b=fBill(c),action=b&&!b.paid?`<button class="map-pay" type="button" onclick="fClose();formalPay('${c.id}','${b.id}')">去繳款</button>`:!b?`<button class="map-pay" type="button" onclick="fClose();formalBill('${c.id}')">新增本月帳單</button>`:'';if(c.active)document.querySelector('#detailContent').insertAdjacentHTML('beforeend',`<div class="map-actions">${action}<button type="button" onclick="fClose();formalSettings('${c.id}')">卡片設定</button><button type="button" onclick="fClose();formalTravel('${c.id}')">讓牠去旅行</button></div>`)};
fRender();
